// G5, rc.20 (fix round 1): a self-hosted runner that makes one CodegenRunner.Run per target sweeps
// once, after all of them, through the hash manifest (OrphanSweep.Sweep with the union of every
// run's directories and EmittedPaths). Ownership is the manifest's recorded hash, never a header:
// `// <auto-generated/>` is the .NET convention (Roslyn source generators write it, adopters put it
// on hand-written partials), so a file carrying it that MetaObjects did not record is never touched,
// and an edited orphan is refused by name, as `dotnet meta gen` refuses one. Paths compare
// case-insensitively: on macOS or Windows a case-only rename keeps the old spelling on disk.

using MetaObjects.Loader;
using MetaObjects.Meta;
using Xunit;

namespace MetaObjects.Codegen.Tests;

public sealed class OrphanSweepRunnerTests : IDisposable
{
    private readonly string _root = Path.Combine(Path.GetTempPath(), "mo-runner-sweep-" + Guid.NewGuid().ToString("N"));
    private string Out => Path.Combine(_root, "gen");
    private string State => Path.Combine(_root, ".metaobjects", ".gen-state");

    public OrphanSweepRunnerTests() => Directory.CreateDirectory(_root);
    public void Dispose() { try { Directory.Delete(_root, recursive: true); } catch { } }

    /// <summary>One file per value object, under its package directory when <paramref name="byPackage"/>.</summary>
    private sealed class PerValue(bool byPackage, string dir = "acme/") : IGenerator
    {
        public string Name => "values";
        public IEnumerable<EmittedFile> Generate(GenContext ctx) =>
            ctx.Root.Objects().Select(o => new EmittedFile(
                (byPackage ? dir : "") + $"{o.Name}.g.cs",
                $"// <auto-generated/>\n// Generated by MetaObjects values.\npublic sealed class {o.Name} {{ }}\n"));
    }

    private static MetaRoot Root(params string[] values)
    {
        var children = string.Join(",", values.Select(v => $$"""{ "object.value": { "name": "{{v}}", "children": [ { "field.string": { "name": "x" } } ] } }"""));
        var r = new MetaDataLoader().Load([new InMemoryStringSource($$"""{ "metadata.root": { "package": "acme", "children": [ {{children}} ] } }""", id: "m.json")]);
        Assert.Empty(r.Errors);
        return r.Root;
    }

    private CodegenRunner.RunResult Run(MetaRoot root, IGenerator generator, string? outDir = null) =>
        CodegenRunner.Run(new GenConfig { OutDir = outDir ?? Out, Namespace = "Acme", GenStateDir = State, ProjectRoot = _root },
            root, [generator]);

    private string At(string rel) => Path.Combine(Out, rel);

    private OrphanSweep.Result Sweep(IEnumerable<CodegenRunner.RunResult> runs, string[] dirs, bool reportUnrecorded = false, bool dryRun = false) =>
        OrphanSweep.Sweep(State, _root, dirs.Select(d => (d, "")).ToList(),
            runs.SelectMany(r => r.EmittedPaths).ToHashSet(StringComparer.Ordinal), reportUnrecorded: reportUnrecorded, dryRun: dryRun);

    [Fact]
    public void A_layout_change_is_swept_through_the_manifest()
    {
        Run(Root("Alpha", "Beta"), new PerValue(byPackage: false));
        var moved = Run(Root("Alpha", "Beta"), new PerValue(byPackage: true));
        Assert.True(File.Exists(At("Alpha.g.cs")));

        var swept = Sweep([moved], [Out]);
        Assert.Equal(["Alpha.g.cs", "Beta.g.cs"], swept.Removed);
        Assert.False(File.Exists(At("Alpha.g.cs")));
        Assert.True(File.Exists(At("acme/Alpha.g.cs")));
    }

    [Fact]
    public void A_dry_run_reports_and_removes_nothing()
    {
        Run(Root("Alpha"), new PerValue(byPackage: false));
        var moved = Run(Root("Alpha"), new PerValue(byPackage: true));
        Assert.Equal(["Alpha.g.cs"], Sweep([moved], [Out], dryRun: true).Removed);
        Assert.True(File.Exists(At("Alpha.g.cs")));
        // The manifest still records it, so the real sweep removes it.
        Assert.Equal(["Alpha.g.cs"], Sweep([moved], [Out]).Removed);
    }

    [Fact]
    public void A_foreign_auto_generated_file_is_never_touched()
    {
        // A Roslyn source generator's output, and a hand-written partial carrying the marker to quiet analyzers.
        Directory.CreateDirectory(At("obj-gen"));
        File.WriteAllText(At("obj-gen/Regex.g.cs"), "// <auto-generated/>\n#nullable enable\npartial class R { }\n");
        File.WriteAllText(At("Quiet.cs"), "// <auto-generated/>\npublic partial class Alpha { }\n");
        var run = Run(Root("Alpha"), new PerValue(byPackage: false));

        var swept = Sweep([run], [Out], reportUnrecorded: true);
        Assert.Empty(swept.Removed);
        Assert.Empty(swept.Refused);
        Assert.Empty(swept.Unrecorded);
        Assert.True(File.Exists(At("obj-gen/Regex.g.cs")));
        Assert.True(File.Exists(At("Quiet.cs")));
    }

    [Fact]
    public void An_edited_orphan_is_refused_by_name()
    {
        Run(Root("Alpha", "Beta"), new PerValue(byPackage: false));
        File.AppendAllText(At("Beta.g.cs"), "// my edit\n");
        var after = Run(Root("Alpha"), new PerValue(byPackage: false));

        var swept = Sweep([after], [Out]);
        Assert.Empty(swept.Removed);
        Assert.Equal(["gen/Beta.g.cs"], swept.Refused);
        Assert.True(File.Exists(At("Beta.g.cs")));
    }

    [Fact]
    public void A_case_only_rename_keeps_the_file_it_just_wrote()
    {
        // On macOS or Windows, overwriting Alpha.g.cs through the path ALPHA.g.cs keeps the old name, so
        // the file on disk is spelled differently from the path the run emitted. Simulated here on any
        // file system: the run emitted the upper-case spelling.
        var run = Run(Root("Alpha"), new PerValue(byPackage: false));
        var emitted = run.EmittedPaths.Select(p => Path.Combine(Path.GetDirectoryName(p)!, Path.GetFileName(p).ToUpperInvariant())).ToHashSet();
        var swept = OrphanSweep.Sweep(State, _root, [(Out, "")], emitted);
        Assert.Empty(swept.Removed);
        Assert.True(File.Exists(At("Alpha.g.cs")));
    }

    [Fact]
    public void A_directory_whose_case_changed_keeps_its_files()
    {
        var run = Run(Root("Alpha"), new PerValue(byPackage: true, dir: "acme/"));
        var emitted = run.EmittedPaths.Select(p => p.Replace(Path.DirectorySeparatorChar + "acme" + Path.DirectorySeparatorChar,
            Path.DirectorySeparatorChar + "ACME" + Path.DirectorySeparatorChar, StringComparison.Ordinal)).ToHashSet();
        Assert.Contains(emitted, p => p.Contains("ACME", StringComparison.Ordinal));
        var swept = OrphanSweep.Sweep(State, _root, [(Out, "")], emitted);
        Assert.Empty(swept.Removed);
        Assert.True(File.Exists(At("acme/Alpha.g.cs")));
    }

    [Fact]
    public void Several_runs_sweep_their_union_and_nested_directories_survive()
    {
        var inner = Path.Combine(Out, "inner");
        var outer = Run(Root("Alpha"), new PerValue(byPackage: false));
        var nested = Run(Root("Beta"), new PerValue(byPackage: false), outDir: inner);
        // Swept alone, the outer run's sweep would see the inner run's recorded files as orphans.
        var swept = Sweep([outer, nested], [Out, inner]);
        Assert.Empty(swept.Removed);
        Assert.True(File.Exists(Path.Combine(inner, "Beta.g.cs")));
        Assert.True(File.Exists(At("Alpha.g.cs")));
    }

    [Fact]
    public void Output_written_before_the_manifest_is_reported_never_deleted()
    {
        // A file an earlier, manifest-less run wrote: MetaObjects' own header, but no recorded hash, so
        // an edit to it cannot be told from an untouched copy.
        Directory.CreateDirectory(Out);
        File.WriteAllText(At("Legacy.g.cs"), "// <auto-generated/>\n// Generated by MetaObjects values.\npublic sealed class Legacy { }\n");
        var run = Run(Root("Alpha"), new PerValue(byPackage: false));

        var swept = Sweep([run], [Out], reportUnrecorded: true);
        Assert.Empty(swept.Removed);
        Assert.Equal(["gen/Legacy.g.cs"], swept.Unrecorded);
        Assert.True(File.Exists(At("Legacy.g.cs")));
        Assert.Empty(Sweep([run], [Out]).Unrecorded);
    }
}
